const app = express();

// CORS config - control which origins can access your API
const corsOrigins = process.env.CORS_ORIGINS || '*';
if (corsOrigins !== '*') {
  app.use(require('cors')({
    origin: corsOrigins.split(',').map(o => o.trim()),
    credentials: true
  }));
}

// Health check endpoint - no timestamp for cleaner monitoring
