  const users = [
    { id: 1, name: 'Alice', email: process.env.TEST_USER_1_EMAIL || 'alice@example.com' },
    { id: 2, name: 'Bob', email: process.env.TEST_USER_2_EMAIL || 'bob@example.com' },
  ];

  app.get('/users', (req, res) => {
    res.json(users);
  });
}

// ============================================================
