function validateDatabaseUrl(dbUrl) {
  try {
    const parsed = new URL(dbUrl);

    if (parsed.protocol !== 'postgresql:' && parsed.protocol !== 'postgres:') {
      return { valid: false, reason: 'Invalid protocol (must be postgresql://)' };
    }

    const port = parseInt(parsed.port || '5432');
    if (port < 1 || port > 65535) {
      return { valid: false, reason: 'Invalid port number' };
    }

    if (dbUrl.includes('CANARY')) {
      return {
        valid: false,
        reason: 'CANARY severity: Test/simulated credential',
        is_canary: true
      };
    }

    if (parsed.hostname.includes('.internal') || parsed.hostname === 'db.internal') {
      return {
        valid: false,
        reason: 'Likely Stale: References internal/legacy service',
        is_legacy: true,
        hostname: parsed.hostname
      };
    }

    if (dbUrl.includes('admin:password') || dbUrl.includes(':THIS_IS_A_BAD_PASSWORD')) {
      return {
        valid: false,
        reason: 'Security Risk: Default or placeholder password detected',
        is_weak: true
      };
    }

    return { valid: true, hostname: parsed.hostname, port };
  } catch (error) {
    return { valid: false, reason: `Invalid URL format: ${error.message}` };
  }
}

