  const isCanonical = /^[A-Z]{4}[0-9A-Z]{16}$/.test(accessKeyId);
  const isCanary = accessKeyId.includes('CANARY');

  if (!isCanonical && !isCanary) {
    return {
      valid: false,
      reason: isCanonical
