const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path?.join('.') || 'unknown',
        message: err.msg
      }))
    });
  }
  next();
};

const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

const handleAsyncError = (err, req, res, next) => {
  // Log error securely (don't expose sensitive info)
  console.error('[Security Error]', {
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Respond with appropriate status code
  const statusCode = err.statusCode || 500;

  // Security: Don't expose stack traces to client in production
  const errorResponse = process.env.NODE_ENV === 'development' ? {
    error: err.message,
    stack: err.stack
  } : {
    error: err.message || 'Internal server error'
  };

  // Warn about potential security issues in error messages
  if (err.code === 'ENOENT') {
    console.warn('[Security Warning] File not found:', err.path);
  }
  if (err.name === 'SyntaxError' && err.status === 400 && 'body' in err) {
    console.warn('[Security Warning] Potential JSON injection attempt');
  }

  res.status(statusCode).json(errorResponse);
};

