  process.exit(1);
});

// ============== START SERVER ==============

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`\n// Secure server running on port ${PORT}`);
  console.log(`// Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`// Health check: http://localhost:${PORT}/health`);
});

